-- One-time clean-up: the same designation typed in different spellings becomes the list's spelling.
-- Only the spellings listed in these maps change (matched without regard to capitals); anything else is left exactly as it was.

-- Onboarding: position
UPDATE records SET data = json_set(data, '$.position', (SELECT mp.value FROM json_each('{"barista":"Barista","brista":"Barista","cashier":"Cashier","casheir":"Cashier","team leader":"Team Leader","team":"Team Leader","store manager":"Store Manager","sm":"Store Manager","manager":"Store Manager","cleaner":"Cleaner","waiter":"Waiter","runner":"Runner","busser":"Busser","dispatcher":"Dispatcher","production operator":"Production Operator"}') mp WHERE mp.key = lower(trim(json_extract(data, '$.position')))))
WHERE module = 'onboarding' AND (SELECT mp.value FROM json_each('{"barista":"Barista","brista":"Barista","cashier":"Cashier","casheir":"Cashier","team leader":"Team Leader","team":"Team Leader","store manager":"Store Manager","sm":"Store Manager","manager":"Store Manager","cleaner":"Cleaner","waiter":"Waiter","runner":"Runner","busser":"Busser","dispatcher":"Dispatcher","production operator":"Production Operator"}') mp WHERE mp.key = lower(trim(json_extract(data, '$.position')))) IS NOT NULL AND (SELECT mp.value FROM json_each('{"barista":"Barista","brista":"Barista","cashier":"Cashier","casheir":"Cashier","team leader":"Team Leader","team":"Team Leader","store manager":"Store Manager","sm":"Store Manager","manager":"Store Manager","cleaner":"Cleaner","waiter":"Waiter","runner":"Runner","busser":"Busser","dispatcher":"Dispatcher","production operator":"Production Operator"}') mp WHERE mp.key = lower(trim(json_extract(data, '$.position')))) IS NOT json_extract(data, '$.position');

-- Store visit reports: position on each staff row (row order kept)
UPDATE sv_reports SET body = json_set(body, '$.team.rows', json((
    SELECT json_group_array(json(CASE WHEN m IS NOT NULL THEN json_set(v, '$.position', m) ELSE v END))
    FROM (SELECT r.key k, r.value v, (SELECT mp.value FROM json_each('{"barista":"Barista","brista":"Barista","cashier":"Cashier","casheir":"Cashier","team leader":"Team Leader","team":"Team Leader","store manager":"Store Manager","sm":"Store Manager","manager":"Store Manager","cleaner":"Cleaner","waiter":"Waiter","runner":"Runner","busser":"Busser","dispatcher":"Dispatcher","production operator":"Production Operator"}') mp WHERE mp.key = lower(trim(json_extract(r.value, '$.position')))) m FROM json_each(sv_reports.body, '$.team.rows') r ORDER BY r.key))))
WHERE EXISTS (SELECT 1 FROM json_each(sv_reports.body, '$.team.rows') j WHERE (SELECT mp.value FROM json_each('{"barista":"Barista","brista":"Barista","cashier":"Cashier","casheir":"Cashier","team leader":"Team Leader","team":"Team Leader","store manager":"Store Manager","sm":"Store Manager","manager":"Store Manager","cleaner":"Cleaner","waiter":"Waiter","runner":"Runner","busser":"Busser","dispatcher":"Dispatcher","production operator":"Production Operator"}') mp WHERE mp.key = lower(trim(json_extract(j.value, '$.position')))) IS NOT NULL AND (SELECT mp.value FROM json_each('{"barista":"Barista","brista":"Barista","cashier":"Cashier","casheir":"Cashier","team leader":"Team Leader","team":"Team Leader","store manager":"Store Manager","sm":"Store Manager","manager":"Store Manager","cleaner":"Cleaner","waiter":"Waiter","runner":"Runner","busser":"Busser","dispatcher":"Dispatcher","production operator":"Production Operator"}') mp WHERE mp.key = lower(trim(json_extract(j.value, '$.position')))) IS NOT json_extract(j.value, '$.position'));

-- Trainers: designation
UPDATE trainers SET designation = (SELECT mp.value FROM json_each('{"trainer":"Trainer","senior trainer":"Senior Trainer","training manager":"Training Manager"}') mp WHERE mp.key = lower(trim(designation)))
WHERE (SELECT mp.value FROM json_each('{"trainer":"Trainer","senior trainer":"Senior Trainer","training manager":"Training Manager"}') mp WHERE mp.key = lower(trim(designation))) IS NOT NULL AND (SELECT mp.value FROM json_each('{"trainer":"Trainer","senior trainer":"Senior Trainer","training manager":"Training Manager"}') mp WHERE mp.key = lower(trim(designation))) IS NOT designation;
